/// <summary>
/// CB223_PalletRounding
/// Batch service class for Post pricing order optimisation
/// </summary>
class METPostPricingOrderOptimisationTaskService extends METSysOperationTaskService
{
    guid    topPickingProcessId;
    SalesId salesId;

}

Method.Source:
/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METPostPricingOrderOptimisationContract</c>.
/// </param>
public void process(METPostPricingOrderOptimisationContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Process the batch tasks.
/// </summary>
/// <param name = "_readPast">Read past table setting.</param>
public void processTask(boolean _readPast)
{
    while (this.getSalesIdFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (this.salesId)
            {
                // execute optimisation processes after PE pricing update in FO
                this.execute(this.salesId);

                // TODO update status to optimisation completed once pallet rounding, quota and credit check completed
            }
        }
        catch (Exception::Error)
        {
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Initializes the object.
/// </summary>
protected void initialise()
{
    super();

    // get the topPickingProcessId from the contract
    METPostPricingOrderOptimisationContract contract = dataContract as METPostPricingOrderOptimisationContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
}

/// <summary>
/// Executes the main processes pallet rounding, quota min/max and leter credit check.
/// </summary>
/// <param name = "_salesId">Sales order to substitute.</param>
private void execute(SalesId _salesId)
{
    //METPostSalesOrderCreationProcessingContract contract = dataContract as METPostSalesOrderCreationProcessingContract;

    // process pallet rounding
    setPrefix(strFmt("Sales order %1 - Pallet ronding", _salesId));
    METSalesTablePalletRoundingProcess palletRoundingProcess = METSalesTablePalletRoundingProcess::construct(_salesId);
    palletRoundingProcess.run();

    // CB202 - Quota Min/Max PLACEHOLDER
}

/// <summary>
/// Get sales order id to substitute from the top picking queue <c>METPostPricingOrderOptimisationQueue</c>
/// </summary>
/// <param name = "_processId">Guid created and added in the contract <c>METPostPricingOrderOptimisationContract</c></param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>Get sales order id to substitute</returns>
private SalesId getSalesIdFromTopPickingQueue(guid _processId, boolean _readPast)
{
    METPostPricingOrderOptimisationQueue postQueue;

    #OCCRetryCount
    int backOffWait;
    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    postQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock SalesId
        from postQueue
        where postQueue.ProcessId == _processId;

        if (postQueue.RecId)
        {
            this.salesId = postQueue.SalesId;

            postQueue.delete();
        }
        else
        {
            // no sales order id found from top picking queue
            this.salesId = '';
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return this.salesId;  
}
